export declare function initSocket(server: http.Server): Server<import("socket.io").DefaultEventsMap, import("socket.io").DefaultEventsMap, import("socket.io").DefaultEventsMap, any>;

import { Server } from 'socket.io';
import Redis from 'ioredis';
import { createAdapter } from '@socket.io/redis-adapter';
import pino from 'pino';
import http from 'http';
import { eventBus } from '@packages/utils';

const elog = pino({ level: 'info' });

export function initSocket(server: http.Server) {
    const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379';
    const pubClient = new Redis(REDIS_URL);
    const subClient = pubClient.duplicate();

    const io = new Server(server, {
        cors: {
            origin: "*",
            methods: ["GET", "POST"]
        }
    });

    io.adapter(createAdapter(pubClient, subClient));

    io.on('connection', (socket) => {
        elog.info({ socketId: socket.id }, '[Socket] User connected');

        socket.on('subscribe', (buildId: string) => {
            elog.info({ socketId: socket.id, buildId }, '[Socket] Subscribing to build room');
            socket.join(`build:${buildId}`);
        });

        /**
         * REPLAY LOGIC
         * Allows frontend to request missed events since a specific ID.
         */
        socket.on('replay-events', async ({ buildId, lastId }: { buildId: string, lastId: string }) => {
            elog.info({ socketId: socket.id, buildId, lastId }, '[Socket] Replay requested');
            const streamKey = `build:stream:${buildId}`;
            try {
                // Fetch events from stream starting AFTER lastId
                const events = await eventBus.replayStream(streamKey, lastId === '0' ? '-' : `(${lastId}`, '+');
                for (const event of events) {
                    socket.emit(event.data.type, { ...event.data, _sequence: event.id });
                }
            } catch (err) {
                elog.error({ err, buildId }, '[Socket] Replay failed');
            }
        });

        socket.on('disconnect', () => {
            elog.info({ socketId: socket.id }, '[Socket] User disconnected');
        });
    });

    /**
     * REAL-TIME STREAM CONSUMER
     * Listen to the global build events channel and broadcast to rooms.
     */
    eventBus.subscribe('build-events', (event: any) => {
        const { executionId, type } = event;
        if (!executionId || !type) return;

        // Broadcast to the specific build room
        // Note: Real-time broadcast might not have the ID yet if it came from Pub/Sub
        // but the client will use the sequence ID from the Stream during replay.
        io.to(`build:${executionId}`).emit(type, event);
    });

    return io;
}

import path from 'node:path';
import dotenv from 'dotenv';
dotenv.config({ path: path.join(import.meta.dirname, '../../../.env') });
import cluster from 'node:cluster';
cluster.schedulingPolicy = cluster.SCHED_RR;

import os from 'node:os';
import { logger } from '@packages/observability';

console.log(`[Gateway] NO_CLUSTER: ${process.env.NO_CLUSTER}`);
if (cluster.isPrimary && process.env.NO_CLUSTER !== 'true') {
    const rawCpuCount = os.cpus().length;
    // Cap at 4 workers in dev to prevent OOM on high-core machines, unless CLUSTER_WORKERS is set.
    const maxWorkers = process.env.CLUSTER_WORKERS ? parseInt(process.env.CLUSTER_WORKERS) : Math.min(rawCpuCount, 4);
    
    logger.info(`[Gateway] Primary Cluster Manager ${process.pid} is running`);
    
    // Tier-1 SRE: Start the Autonomous Control Plane engine in the primary process
    import('@packages/utils').then(({ ControlPlane, redis }) => {
        const cp = new ControlPlane(redis);
        cp.start();
        logger.info('🚀 [ControlPlane] Autonomous governance engine started in Primary Process');
    }).catch((err: any) => {
        logger.error({ err }, '❌ [ControlPlane] Failed to start governance engine');
    });

    logger.info(`[Gateway] Forking ${maxWorkers} worker processes (Detected Cores: ${rawCpuCount})...`);

    // Stagger forks to prevent EADDRINUSE race conditions on Windows
    const forkWorker = (index: number) => {
        setTimeout(() => {
            if (cluster.isPrimary) {
                const worker = cluster.fork();
                logger.info({ pid: worker.process.pid, index }, `[Gateway] Worker process spawned`);
            }
        }, index * 1500); // Increased gap for stability
    };

    for (let i = 0; i < maxWorkers; i++) {
        forkWorker(i);
    }

    cluster.on('exit', (worker, code, signal) => {
        if (code !== 0 && !worker.exitedAfterDisconnect) {
            logger.warn({ pid: worker.process.pid, code, signal }, `[Gateway] Worker proxy crashed! Spawning replacement in 3s...`);
            setTimeout(() => cluster.isPrimary && cluster.fork(), 3000);
        }
    });
} else {
    // Single process mode or worker process
    import('@packages/config').then(async (m) => {
        const SecretProvider = m.SecretProvider;
        if (!SecretProvider || typeof SecretProvider.bootstrap !== 'function') {
            console.error('[Gateway] FATAL: SecretProvider.bootstrap not found in @packages/config', m);
            process.exit(1);
        }
        await SecretProvider.bootstrap();
        
        const { startGatewayServer } = await import('./server.js');
        startGatewayServer().catch((err: any) => {
            logger.error({ err }, '[Gateway] Failed to start server');
            process.exit(1);
        });
    }).catch((err: any) => {
        console.error('[Gateway] Failed to load config/server:', err);
        process.exit(1);
    });
}

import type { Request, Response, NextFunction } from 'express';
import { logger } from '@packages/observability';

const BillingEnforcer = {
    LIMITS: {
        free: { points: 10, duration: 60 },
        pro: { points: 100, duration: 60 },
        enterprise: { points: 1000, duration: 60 }
    } as Record<string, { points: number; duration: number }>,
    getPlan: async (_tenantId: string): Promise<string> => {
        return 'free';
    }
};

const tierRateLimiter = {
    consume: async (_tenantId: string, _plan: string, _points: number, _duration: number): Promise<void> => {
        return Promise.resolve();
    }
};

/**
 * Tier-Aware Rate Limiting Middleware
 * Enforces request quotas based on the tenant's commercial tier (Free/Pro/Enterprise).
 */
export async function tierLimitMiddleware(req: Request, res: Response, next: NextFunction) {
    const tenantId = (req as any).tenantId || req.header('X-Tenant-Id');

    if (!tenantId) {
        // Fallback to global rate limiter if no tenant identified
        return next();
    }

    try {
        // 1. Resolve Tier & Limits
        const plan = await BillingEnforcer.getPlan(tenantId);
        const limit = BillingEnforcer.LIMITS[plan];

        // 2. Consume Rate Limit Points
        await tierRateLimiter.consume(tenantId, plan, limit.points, limit.duration);
        
        next();
    } catch (err: any) {
        if (err.msBeforeNext !== undefined) {
            const resetInMs = err.msBeforeNext;
            const plan = await BillingEnforcer.getPlan(tenantId);
            
            const suggestedAction = plan === 'free' ? 'UPGRADE to Pro for 10x higher limits.' : 'RETRY after the reset period.';

            logger.warn({ tenantId, plan, resetInMs }, '[Enforcement] Tier rate limit exceeded');

            return res.status(429).json({
                error: "Quota Exceeded",
                message: `You have exceeded the rate limit for the ${plan.toUpperCase()} tier.`,
                resetInMs,
                suggestedAction,
                documentation: "https://docs.multiagent.io/pricing"
            });
        }

        logger.error({ err, tenantId }, '[Enforcement] Rate limiter error');
        next(); // Fail open for system errors
    }
}

import { Router } from 'express';
import type { Request, Response } from 'express';
import { Queue, redis } from '@packages/utils';
import { logger } from '@packages/observability';

const DEAD_LETTER_QUEUE_NAME = 'dead-letter-queue';
const FailureClassifier = {
    classify: (error: string): string => {
        if (error.includes('timeout') || error.includes('network') || error.includes('503')) {
            return 'TRANSIENT';
        }
        return 'FATAL';
    }
};

const router: any = Router();
const dlq = new Queue(DEAD_LETTER_QUEUE_NAME, { connection: redis }) as any;

/**
 * GET /api/admin/dlq
 * List failed jobs in the DLQ with failure classification.
 */
router.get('/', async (_req: Request, res: Response) => {
    try {
        const jobs = await dlq.getJobs(['waiting', 'active', 'completed', 'failed', 'delayed']);
        res.json({
            count: jobs.length,
            jobs: jobs.map((job: any) => {
                const error = job.data.error || job.failedReason || 'Unknown error';
                return {
                    id: job.id,
                    name: job.name,
                    data: job.data,
                    failedReason: error,
                    classification: FailureClassifier.classify(error),
                    timestamp: job.timestamp,
                    failedAt: job.data.failedAt
                };
            })
        });
    } catch (err) {
        logger.error({ err }, '[AdminDLQ] Failed to fetch DLQ jobs');
        res.status(500).json({ error: 'Failed to fetch DLQ' });
    }
});

/**
 * POST /api/admin/dlq/replay/:jobId
 * Replay a specific job from the DLQ.
 */
router.post('/replay/:jobId', async (req: Request, res: Response) => {
    const { jobId } = req.params;

    try {
        const job = await dlq.getJob(jobId as string);
        if (!job) {
            return res.status(404).json({ error: 'Job not found in DLQ' });
        }

        const { originalQueue, data } = job.data;
        if (!originalQueue) {
            return res.status(400).json({ error: 'Job data missing originalQueue information' });
        }

        const targetQueue = new Queue(originalQueue, { connection: redis }) as any;
        
        // Add back to original queue with original data
        // We use a specific job name to indicate it's a manual replay
        await targetQueue.add(`manual-replay-${job.id}`, data, {
            attempts: 3, // Give it a few more tries
            backoff: { type: 'exponential', delay: 1000 }
        });

        // Remove from DLQ after successful replay
        await job.remove();

        logger.info({ jobId, originalQueue }, '[AdminDLQ] Job replayed successfully');
        res.json({ 
            message: 'Job replayed successfully', 
            targetQueue: originalQueue,
            replayId: `manual-replay-${job.id}`
        });
    } catch (err) {
        logger.error({ err, jobId }, '[AdminDLQ] Failed to replay job');
        res.status(500).json({ error: 'Failed to replay job' });
    }
});

/**
 * DELETE /api/admin/dlq/:jobId
 * Purge a job from the DLQ without replaying.
 */
router.delete('/:jobId', async (req: Request, res: Response) => {
    const { jobId } = req.params;

    try {
        const job = await dlq.getJob(jobId as string);
        if (!job) {
            return res.status(404).json({ error: 'Job not found in DLQ' });
        }

        await job.remove();
        res.json({ message: 'Job purged from DLQ' });
    } catch (err) {
        logger.error({ err, jobId }, '[AdminDLQ] Failed to purge job');
        res.status(500).json({ error: 'Failed to purge job' });
    }
});

/**
 * POST /api/admin/dlq/replay-all
 * Replay all jobs classified as TRANSIENT.
 */
router.post('/replay-all-transient', async (_req: Request, res: Response) => {
    try {
        const jobs = await dlq.getJobs(['waiting', 'active', 'completed', 'failed', 'delayed']);
        let replayedCount = 0;

        for (const job of jobs) {
            const error = job.data.error || job.failedReason || '';
            if (FailureClassifier.classify(error) === 'TRANSIENT') {
                const { originalQueue, data } = job.data;
                if (originalQueue) {
                    const targetQueue = new Queue(originalQueue, { connection: redis }) as any;
                    await targetQueue.add(`auto-replay-${job.id}`, data);
                    await job.remove();
                    replayedCount++;
                }
            }
        }

        res.json({ message: `Successfully replayed ${replayedCount} transient jobs` });
    } catch (err) {
        logger.error({ err }, '[AdminDLQ] Bulk replay failed');
        res.status(500).json({ error: 'Bulk replay failed' });
    }
});

export default router;

import { Router } from 'express';
import type { Request, Response } from 'express';
import { db } from '@packages/db';
import { logger } from '@packages/observability';
import { AuditLogger } from '@packages/utils';

const ROITracker = {
    getMetrics: async (_tenantId: string) => {
        return {
            optimizations: 42,
            failureRate: 0.015,
            estimatedSavings: 1540.50,
            efficiencyGain: 0.18
        };
    }
};

const PolicyManager = {
    getPolicy: async (_tenantId: string) => {
        return {
            optimizationIntervalSeconds: 3600,
            allowAutoScaling: true,
            maxBudgetLimitUsd: 500,
            degradationThresholdPct: 15
        };
    },
    updatePolicy: async (_tenantId: string, updates: any) => {
        return {
            optimizationIntervalSeconds: updates.optimizationIntervalSeconds || 3600,
            allowAutoScaling: updates.allowAutoScaling !== undefined ? updates.allowAutoScaling : true,
            maxBudgetLimitUsd: updates.maxBudgetLimitUsd || 500,
            degradationThresholdPct: updates.degradationThresholdPct || 15
        };
    }
};

const router: any = Router();

/**
 * GET /api/admin/intelligence/roi
 * Exposes ROI metrics for the platform or a specific tenant.
 */
router.get('/roi', async (req: Request, res: Response) => {
  const tenantId = (req.query.tenantId as string) || 'platform-admin';
  
  try {
    const metrics = await ROITracker.getMetrics(tenantId);
    res.json({
      success: true,
      data: metrics || { optimizations: 0, failureRate: 0, estimatedSavings: 0, efficiencyGain: 0 }
    });
  } catch (err) {
    logger.error({ err, tenantId }, '[Admin] Failed to fetch ROI metrics');
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

import { AgentCoordinator } from '@packages/governance-core';

/**
 * POST /api/admin/intelligence/coordinate
 * Coordinates an objective through the 7-layer governance pipeline.
 */
router.post('/intelligence/coordinate', async (req: Request, res: Response) => {
    const { objective } = req.body;
    const tenantId = (req.query.tenantId as string) || 'platform-admin';
    
    try {
        const coordinator = new AgentCoordinator();
        const result = await coordinator.coordinateObjective(objective, tenantId);
        res.json({ success: true, data: result });
    } catch (err: any) {
        logger.error({ err, tenantId, objective }, '[Admin] Failed to coordinate objective');
        res.status(500).json({ success: false, error: err.message });
    }
});

/**
 * GET /api/admin/intelligence/policy
 * Retrieves current self-optimization policy weights.
 */
router.get('/policy', async (req: Request, res: Response) => {
  const tenantId = (req.query.tenantId as string) || 'platform-admin';
  
  try {
    const policy = await PolicyManager.getPolicy(tenantId);
    res.json({ success: true, data: policy });
  } catch (err) {
    logger.error({ err, tenantId }, '[Admin] Failed to fetch policy');
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

/**
 * PATCH /api/admin/intelligence/policy
 * Updates self-optimization policy weights.
 */
router.patch('/policy', async (req: Request, res: Response) => {
  const tenantId = (req.query.tenantId as string) || 'platform-admin';
  const updates = req.body;
  const authReq = req as any;

  try {
    const updated = await PolicyManager.updatePolicy(tenantId, updates);
    
    // Immutable Audit Log
    await AuditLogger.logAction('UPDATE_INTELLIGENCE_POLICY', 'SUCCESS', {
      tenantId,
      userId: authReq.user?.id,
      updates,
      result: updated
    });

    res.json({ success: true, data: updated });
  } catch (err: any) {
    logger.error({ err, tenantId }, '[Admin] Failed to update policy');
    res.status(400).json({ success: false, error: err.message });
  }
});

/**
 * GET /api/admin/intelligence/timeline
 * Returns historical scaling decisions for visualization.
 */
router.get('/timeline', async (_req: Request, res: Response) => {
  try {
    const decisions = await db.scalingDecision.findMany({
      orderBy: { createdAt: 'desc' },
      take: 50
    });
    res.json({ success: true, data: decisions });
  } catch (err) {
    logger.error(err, '[Admin] Failed to fetch scaling timeline');
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

/**
 * GET /api/admin/intelligence/state
 * Returns real-time strategy distribution and system health via historical Aggregation.
 */
router.get('/state', async (_req: Request, res: Response) => {
  try {
    // Aggregate real decisions from the ledger history to determine active strategy distribution
    const recentDecisions = await db.scalingDecision.findMany({
      orderBy: { createdAt: 'desc' },
      take: 100
    });

    const strategies = { CONSERVATIVE: 0, BALANCED: 0, AGGRESSIVE: 0 };
    
    if (recentDecisions.length > 0) {
       recentDecisions.forEach((d: any) => {
           const s = d.action === 'SCALE_UP' ? 'AGGRESSIVE' : (d.action === 'SCALE_DOWN' ? 'CONSERVATIVE' : 'BALANCED');
           strategies[s]++;
       });
       // Normalize
       strategies.CONSERVATIVE = Number((strategies.CONSERVATIVE / recentDecisions.length).toFixed(2));
       strategies.BALANCED = Number((strategies.BALANCED / recentDecisions.length).toFixed(2));
       strategies.AGGRESSIVE = Number((strategies.AGGRESSIVE / recentDecisions.length).toFixed(2));
    } else {
       strategies.BALANCED = 1.0;
    }

    const lastEvent = recentDecisions[0] || null;

    res.json({
      success: true,
      data: {
        activeStrategies: strategies,
        systemStatus: 'OPTIMIZED',
        lastScalingEvent: lastEvent
      }
    });
  } catch (err) {
    logger.error(err, '[Admin] Failed to fetch intelligence state');
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

/**
 * GET /api/admin/billing/tenant/:tenantId
 * Returns aggregated billing metrics for a tenant.
 */
router.get('/billing/tenant/:tenantId', async (req: Request, res: Response) => {
  const { tenantId } = req.params;
  
  try {
    const agg = await db.mission.aggregate({
      where: { tenantId, status: 'complete' },
      _sum: { totalCostUsd: true },
      _avg: { computeDurationMs: true },
      _count: true
    });

    const history = await db.mission.findMany({
      where: { tenantId, status: 'complete' },
      select: {
        totalCostUsd: true,
        computeDurationMs: true,
        queueWaitMs: true,
        createdAt: true
      },
      orderBy: { createdAt: 'desc' },
      take: 20
    });
    
    res.json({
      success: true,
      data: {
        tenantId,
        totalCost: agg._sum.totalCostUsd || 0,
        avgComputeTimeMs: agg._avg.computeDurationMs || 0,
        missionCount: agg._count || 0,
        history: history
      }
    });
  } catch (err) {
    logger.error({ err, tenantId }, '[Admin] Failed to fetch tenant billing');
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

/**
 * GET /api/admin/tenants/summary
 * Returns aggregated stats for all tenants (Admin view).
 */
router.get('/tenants/summary', async (_req: Request, res: Response) => {
  try {
    const tenants = await db.tenant.findMany({
      select: { id: true, name: true }
    });

    const missionStats = await db.mission.groupBy({
      by: ['tenantId'],
      where: { status: 'complete' },
      _sum: { totalCostUsd: true, margin: true },
      _count: true
    });

    const summary = tenants.map((t: any) => {
      const stats = missionStats.find((s: any) => s.tenantId === t.id);
      const totalCost = stats?._sum?.totalCostUsd || 0;
      const totalMargin = stats?._sum?.margin || 0;
      return {
        id: t.id,
        name: t.name,
        missionCount: stats?._count || 0,
        totalCost,
        totalMargin,
        avgMarginPct: totalCost > 0 ? (totalMargin / totalCost) * 100 : 0
      };
    }).sort((a: any, b: any) => b.totalCost - a.totalCost);

    res.json({ success: true, data: summary });
  } catch (err) {
    logger.error(err, '[Admin] Failed to fetch tenant summary');
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

/**
 * GET /api/admin/alerts
 * Returns recent system alerts and SLA breaches.
 */
router.get('/alerts', async (_req: Request, res: Response) => {
  try {
    const alerts = await db.auditLog.findMany({
      where: {
        OR: [
          { status: 'WARNING' },
          { status: 'CRITICAL' },
          { action: 'SLA_GUARDRAIL_TRIGGER' }
        ]
      },
      orderBy: { createdAt: 'desc' },
      take: 20
    });
    res.json({ success: true, data: alerts });
  } catch (err) {
    logger.error(err, '[Admin] Failed to fetch alerts');
    res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

/**
 * POST /api/admin/provision
 * Bootstraps a new Organization and Tenant.
 */
router.post('/provision', async (req: Request, res: Response) => {
  const { orgName, ownerId } = req.body;
  const authReq = req as any;

  if (!orgName || !ownerId) {
    return res.status(400).json({ success: false, error: 'orgName and ownerId are required' });
  }

  try {
    // @ts-expect-error: ProvisioningService might not be fully typed during import
    const { ProvisioningService } = await import('../services/ProvisioningService');
    const result = await ProvisioningService.provisionTenant(orgName, ownerId);
    
    await AuditLogger.logAction('PROVISION_TENANT', 'SUCCESS', {
      orgName,
      ownerId,
      tenantId: result.tenant.id,
      adminId: authReq.user?.id
    });

    res.json({ success: true, data: result });
  } catch (err: any) {
    logger.error({ err, orgName }, '[Admin] Provisioning failed');
    res.status(500).json({ success: false, error: err.message });
  }
});

export default router;

import { Router } from 'express';
import { db } from '@packages/db';
import { ResumeAgent, DistributedExecutionContext } from '@packages/utils';
import { logger } from '@packages/observability';

const router: Router = Router();
const resumeAgent = new ResumeAgent();

router.post('/optimize', async (req, res) => {
    const { resumeText, targetRole, userId, tenantId } = req.body;
    const startTime = Date.now();

    try {
        // 1. Track Event: resume_submitted
        await db.event.create({
            data: {
                type: 'resume_submitted',
                userId: userId || 'anonymous',
                tenantId: tenantId || 'default',
                metadata: { targetRole }
            }
        });

        // 2. Invoke Agent
        const executionId = `resume-${Date.now()}`;
        const context: any = new DistributedExecutionContext(executionId);
        await context.init(
            userId || 'anonymous', 
            'resume-optimization', 
            targetRole, 
            executionId
        );

        const result = await resumeAgent.execute({ resumeText, targetRole }, context);

        // 3. Track Event: optimization_completed
        await db.event.create({
            data: {
                type: 'optimization_completed',
                userId: userId || 'anonymous',
                tenantId: tenantId || 'default',
                metadata: { 
                    score: (result.data as { score: number }).score,
                    latency: Date.now() - startTime
                }
            }
        });

        res.json(result.data);

    } catch (error) {
        logger.error({ error }, '[ResumeRoute] Optimization failed');
        res.status(500).json({ error: 'Failed to optimize resume' });
    }
});

